use super::*;
use semio_framework_job::OriginalJobFixtureCaller;
use semio_framework_value::RetainedAllocationEffect;
fn effect_turn(caller:&mut OriginalJobFixtureCaller,grant:RetainedCloneGrant,run:impl FnOnce(&mut RetainedAllocationEffect<'_>)->Result<RetainedCloneProgress,ValueError>)->(RetainedCloneProgress,(usize,usize)){
 let(progress,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant,|cx|{let Some((result,performed))=cx.with_original_effect(grant,|_,effect|run(effect))?else{return Ok(Default::default())};let progress=result?;cx.consume_retained(progress)?;cx.consume_fuel(u64::try_from(performed).unwrap_or(u64::MAX));Ok(progress)}));
 (progress.unwrap(),(heap.requested_bytes,heap.released_bytes))
}
#[test]
fn original_window_catalog_sources_and_tickets_match_physical_original_grants(){
 type O=crate::original_genesis_tests::Owner;let law:serde_json::Value=serde_json::from_str(include_str!("./🧫️fixtures/🔣️.json")).unwrap();let row=law["grant"].as_array().unwrap();let grant=RetainedCloneGrant{maximum_items:row[0].as_u64().unwrap()as usize,maximum_copy_bytes:row[1].as_u64().unwrap()as usize,maximum_capacity_bytes:row[2].as_u64().unwrap()as usize,maximum_release_bytes:row[3].as_u64().unwrap()as usize,maximum_depth:row[4].as_u64().unwrap()as usize};
 for axis in [0,1,2,4]{let mut denied=grant;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=0,2=>denied.maximum_capacity_bytes=0,_=>denied.maximum_depth=0}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||bounded_window_config_store_owners::<O>(denied));assert!(result.is_err());let error=result.err().unwrap();assert!(error.owners.is_none());assert_eq!(error.progress,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
 let((mut owners,p),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||bounded_window_config_store_owners::<O>(grant).map_err(|error|error.error).unwrap());assert!(p.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(owners.original_semantic_issuer_is_shared());assert!(!owners.constructor_is_complete());let mut caller=crate::original_genesis_tests::caller();let mut allocated=p.retained_capacity_bytes;let mut released=0;while !owners.constructor_is_complete(){let(p,heap)=effect_turn(&mut caller,grant,|effect|owners.admit_constructor(effect).map_err(|(error,_)|error));assert!(p.fits(grant));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));allocated+=p.retained_capacity_bytes;released+=p.released_bytes;}
 while !owners.uninstalled_owners_terminal_is_empty(){let(p,heap)=effect_turn(&mut caller,grant,|effect|owners.close_uninstalled_owners_step(effect).map(|step|step.progress()));assert!(p.fits(grant));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));allocated+=p.retained_capacity_bytes;released+=p.released_bytes;assert_ne!(p,Default::default());}assert_eq!(allocated,released);caller.retire(grant);
}